<?php use PHPUnit\Framework\TestCase; class LoginTest extends TestCase { protected function setUp(): void { parent::setUp(); require_once __DIR__ . "/../../config.php"; } public function testLoginPageContainsForm() { ob_start(); include __DIR__ . "/../../login.php"; $output = ob_get_clean(); $this->assertStringContainsString("<form", $output); $this->assertStringContainsString("method=\"post\"", $output); } }
